USE [JamunaBankProcurement];
GO
CREATE OR ALTER PROCEDURE dbo.usp_Comment_Add @RequisitionId BIGINT,@ReqItemId BIGINT=NULL,@CommentType VARCHAR(30),@CommentText NVARCHAR(4000),@ActorEmployeeId VARCHAR(30) AS BEGIN SET NOCOUNT ON; INSERT dbo.COMMENT_NOTE(REQUISITION_ID,REQ_ITEM_ID,COMMENT_TYPE,COMMENT_TEXT,CREATED_BY_EMPLOYEE_ID) VALUES(@RequisitionId,@ReqItemId,@CommentType,@CommentText,@ActorEmployeeId); SELECT '000' RESULT_CODE,N'Success' RESULT_MESSAGE,CONVERT(BIGINT,SCOPE_IDENTITY()) ENTITY_ID,NULL REFERENCE_NO; END;
GO
CREATE OR ALTER PROCEDURE dbo.usp_Comment_GetByRequisition @RequisitionId BIGINT,@ActiveOnly BIT=1 AS BEGIN SET NOCOUNT ON; SELECT * FROM dbo.COMMENT_NOTE WHERE REQUISITION_ID=@RequisitionId AND (@ActiveOnly=0 OR IS_ACTIVE=1) ORDER BY CREATED_DATE; END;
GO
CREATE OR ALTER PROCEDURE dbo.usp_Attachment_Add @EntityType VARCHAR(30),@EntityId BIGINT,@FileName NVARCHAR(255),@OriginalFileName NVARCHAR(255),@StorageKey NVARCHAR(1000),@FileExtension VARCHAR(20)=NULL,@MimeType VARCHAR(150)=NULL,@FileSize BIGINT,@DocumentType VARCHAR(50)=NULL,@ActorEmployeeId VARCHAR(30)
AS BEGIN SET NOCOUNT ON; DECLARE @valid BIT=0; IF @EntityType='REQUISITION' AND EXISTS(SELECT 1 FROM dbo.REQUISITION_HEADER WHERE REQUISITION_ID=@EntityId) SET @valid=1; ELSE IF @EntityType='REQUISITION_ITEM' AND EXISTS(SELECT 1 FROM dbo.REQUISITION_ITEM WHERE REQ_ITEM_ID=@EntityId) SET @valid=1; ELSE IF @EntityType='APPROVAL' AND EXISTS(SELECT 1 FROM dbo.APPROVAL_ACTION WHERE APPROVAL_ID=@EntityId) SET @valid=1; ELSE IF @EntityType='PROCUREMENT_STATUS' AND EXISTS(SELECT 1 FROM dbo.PROCUREMENT_STATUS_HISTORY WHERE STATUS_HISTORY_ID=@EntityId) SET @valid=1; ELSE IF @EntityType='WORK_ORDER' AND EXISTS(SELECT 1 FROM dbo.WORK_ORDER_HEADER WHERE WORK_ORDER_ID=@EntityId) SET @valid=1; ELSE IF @EntityType='COMMENT' AND EXISTS(SELECT 1 FROM dbo.COMMENT_NOTE WHERE COMMENT_ID=@EntityId) SET @valid=1; ELSE IF @EntityType='OTHER' SET @valid=1; IF @valid=0 BEGIN SELECT '001' RESULT_CODE,N'Invalid entity reference' RESULT_MESSAGE,NULL ENTITY_ID,NULL REFERENCE_NO; RETURN; END; INSERT dbo.ATTACHMENT(ENTITY_TYPE,ENTITY_ID,FILE_NAME,ORIGINAL_FILE_NAME,FILE_PATH_OR_STORAGE_KEY,FILE_EXTENSION,MIME_TYPE,FILE_SIZE,DOCUMENT_TYPE,UPLOADED_BY_EMPLOYEE_ID) VALUES(@EntityType,@EntityId,@FileName,@OriginalFileName,@StorageKey,@FileExtension,@MimeType,@FileSize,@DocumentType,@ActorEmployeeId); SELECT '000' RESULT_CODE,N'Success' RESULT_MESSAGE,CONVERT(BIGINT,SCOPE_IDENTITY()) ENTITY_ID,NULL REFERENCE_NO; END;
GO
CREATE OR ALTER PROCEDURE dbo.usp_Attachment_GetByEntity @EntityType VARCHAR(30),@EntityId BIGINT,@ActiveOnly BIT=1 AS BEGIN SET NOCOUNT ON; SELECT * FROM dbo.ATTACHMENT WHERE ENTITY_TYPE=@EntityType AND ENTITY_ID=@EntityId AND (@ActiveOnly=0 OR IS_ACTIVE=1) ORDER BY UPLOADED_DATE; END;
GO
GRANT EXECUTE TO procurement_app_executor;
GO

